$ErrorActionPreference='Stop';Import-Module (Join-Path $PSScriptRoot 'Repato.QaAddinDeployment.psm1') -Force
$r=Join-Path ([IO.Path]::GetTempPath()) ('qa-addin-'+[guid]::NewGuid().ToString('N'));New-Item $r -ItemType Directory|Out-Null;$fx=Join-Path $PSScriptRoot 'DeploymentFixtures';Copy-Item (Join-Path $fx 'artifact.source') (Join-Path $r 'artifact.source');Copy-Item (Join-Path $fx 'manifest.source') (Join-Path $r 'manifest.source');Copy-Item (Join-Path $fx 'artifact.target') (Join-Path $r 'artifact.target');Copy-Item (Join-Path $fx 'manifest.target') (Join-Path $r 'manifest.target')
try{$x=Invoke-QaAddinDeployment (Join-Path $r 'artifact.source') (Join-Path $r 'manifest.source') -TestTargetRoot $r;if(!$x.BackupPaths){throw 'backup missing'};if((Get-FileHash (Join-Path $r 'artifact.target')).Hash -ne $x.ArtifactSha256){throw 'apply hash mismatch'};$dry=Invoke-QaAddinDeployment (Join-Path $r 'artifact.source') (Join-Path $r 'manifest.source') -TestTargetRoot $r -DryRun;if($dry.SideEffectsPerformed){throw 'dry-run side effects'};'QA add-in lifecycle checks passed: 3'}finally{Remove-Item $r -Recurse -Force}
